1	// The order process (SPEC-E): routes every event of the instance to the module that owns the decision, and runs the
2	// settle pass once per tick. Subject = the normalised order id (§3.1). One instance per order.
3	
4	const norm = x => String(x ?? '').trim().replace(/^#/, '').trim().toUpperCase();
5	const fileJson = (files, p) => {
6	  let v = files?.[p];
7	  if (v === undefined) v = p.split('/').reduce((o, k) => (o ? o[k] : undefined), files);
8	  if (typeof v === 'string') { try { v = JSON.parse(v); } catch { return null; } }
9	  return v ?? null;
10	};
11	const deepFind = (v, key, d = 0) => {
12	  if (!v || typeof v !== 'object' || d > 8) return undefined;
13	  if (!Array.isArray(v) && key in v) return v[key];
14	  for (const x of Object.values(v)) { const r = deepFind(x, key, d + 1); if (r !== undefined) return r; }
15	  return undefined;
16	};
17	
18	// R1.3: the published edition with the latest effectiveFrom on or before the date of the order (its own local date)
19	function editionAt(files, at) {
20	  const day = at.slice(0, 10);
21	  let best = null;
22	  for (const k of Object.keys(files ?? {})) {
23	    const m = /^rulebook\/([^/]+)\/edition\.json$/.exec(k);
24	    if (!m) continue;
25	    const e = fileJson(files, k);
26	    if (!e?.effectiveFrom || e.effectiveFrom > day) continue;
27	    if (!best || e.effectiveFrom > best.from) best = { dir: m[1], from: e.effectiveFrom };
28	  }
29	  if (!best) throw new Error(`no edition in force on ${day}`);
30	  return best.dir;
31	}
32	
33	// the carrier's own code → one meaning (§3.3); a code the table does not list is info
34	const COLLECTED = ['collected', 'inTransit', 'delivered'];
35	function meaningOf(files, ed, code) {
36	  const t = fileJson(files, `rulebook/${ed}/carrier-codes.json`);
37	  if (Array.isArray(t)) { const row = t.find(r => r.code === code); return row ? (deepFind(row, 'meaning') ?? 'info') : 'info'; }
38	  return t?.[code] ?? 'info';
39	}
40	
41	const inbound = e => e.channel?.kind === 'inbound';
42	const kindOf = e => {
43	  if (e.source === 'shop') return 'placed';
44	  if (e.source === 'customer-portal') return 'action';
45	  if (e.source === 'carrier') return 'carrier';
46	  return null;
47	};
48	
49	export function tick(input, ctx) {
50	  const files = ctx.files;
51	  let st = input.state ?? { o: null, ed: null, p: null, ord: null, al: false, fids: [], v: null, pc: null };
52	  const events = input.events ?? [];
53	
54	  // An inbound message starts a new instance: it belongs to an open case (merge), to a closed one (close), or is new.
55	  const first = events[0];
56	  if (!st.o && first && inbound(first)) {
57	    let sub = null;
58	    if (kindOf(first) === 'placed') sub = norm(first.payload.orderId);
59	    else if (kindOf(first) === 'action') sub = norm(first.payload.orderRef);
60	    else if (kindOf(first) === 'carrier') {
61	      const rows = ctx.query('orders.fulfilments', { where: { fulfilmentId: norm(first.payload.fulfilmentRef) }, limit: 1 });
62	      sub = rows[0] ? norm(rows[0].orderId) : null;
63	    }
64	    if (!sub) return { decisions: { subject: null, phase: 'none' }, state: st, close: true };
65	    const others = (ctx.instances({ subject: sub }) ?? []).filter(i => i.instance !== input.instance);
66	    if (others.length) return { decisions: { subject: sub, phase: 'merged' }, state: st, merge: { into: others[0].instance } };
67	    if (kindOf(first) !== 'placed') {
68	      // a message about an order that is already closed changes nothing; one about no order at all is answered with nothing
69	      return { decisions: { subject: sub, phase: 'closed' }, state: st, close: true };
70	    }
71	    if (ctx.query('orders.orders', { where: { orderId: sub }, limit: 1 }).length) {
72	      return { decisions: { subject: sub, phase: 'duplicate' }, state: st, close: true };   // R1.4
73	    }
74	  }
75	
76	  for (const e of events) {
77	    if (e.type === 'effect.result' || e.type === 'timer.fired' || String(e.type).startsWith('humanTask.')) {
78	      const owner = ctx.ownerOf(e);
79	      if (owner) { absorb(owner.module, ctx.deliver(e)); continue; }
80	      if (e.type === 'effect.result') readResult(e);
81	      continue;
82	    }
83	    if (e.type === 'migration') { migrate(e); continue; }
84	    const k = kindOf(e);
85	    if (k === 'placed') placed(e);
86	    else if (k === 'action') action(e);
87	    else if (k === 'carrier') carrier(e);
88	  }
89	
90	  // the settle pass: effects that depend on the whole tick's decisions (R3.1 notice, R4.1 processing and starts)
91	  let done = false;
92	  if (st.o && st.al) done = ctx.call('orderflow', st.o, { op: 'settle' }).done;
93	  return {
94	    decisions: { subject: st.o, phase: st.al ? 'recorded' : st.o ? 'allocating' : 'none' },
95	    state: st,
96	    ...(done ? { close: true } : {}),
97	  };
98	
99	  // go-live (§3.5): an order already in flight continues from its records: the order's status and fulfilments, and for
100	  // a processing order each fulfilment's committed reservation, charge and shipment (a fulfilment resumes from them)
101	  function migrate(e) {
102	    const oid = norm(deepFind(e.payload, 'orderId'));
