  "allocate": {
   "args": {
    "type": "object",
    "required": [
     "orderId"
    ],
    "properties": {
     "orderId": {
      "type": "string",
      "maxLength": 80,
      "minLength": 1
     }
    },
    "additionalProperties": false
   },
   "keyed": false,
   "subjectArgs": [
    "orderId"
   ],
   "readOnly": true,
   "batch": false,
   "money": false,
   "description": "The fulfilment plan of an order (read-only): { orderId, fulfilments: [{ fulfilmentId, location, items, available }] }."
  },
  "reserve": {
   "args": {
    "type": "object",
    "required": [
     "orderId",
     "fulfilmentId",
     "location",
     "items"
    ],
    "properties": {
     "orderId": {
      "type": "string",
      "maxLength": 80,
      "minLength": 1
     },
     "fulfilmentId": {
      "type": "string",
      "maxLength": 80,
      "minLength": 1
     },
     "location": {
      "type": "string",
      "maxLength": 40,
      "minLength": 1
     },
     "items": {
      "type": "array",
      "items": {
       "type": "object",
       "required": [
        "sku",
        "qty"
