const MAX_FIX = 3;
const REISSUE_MIN = 120;

// A 400 from a system is our mistake (e.g. a field it renamed): re-issue with the arguments the current schema names.
// A field the schema no longer names is matched to the schema's field of the same type and the closest name; position
// only breaks a tie.
const fixArgs = (v, s) => {
  if (!s || v === null || typeof v !== 'object') return v;
  if (Array.isArray(v)) return v.map(x => fixArgs(x, s.items));
  const props = Object.keys(s.properties ?? {});
  if (!props.length) return v;
  const out = {}, extra = [];
  for (const k of Object.keys(v)) (props.includes(k) ? (out[k] = fixArgs(v[k], s.properties[k])) : extra.push(k));
  let left = (s.required ?? []).filter(k => !(k in out));
  const fits = (val, p) => (p?.type === 'integer' || p?.type === 'number' ? typeof val === 'number'
    : p?.type === 'string' ? typeof val === 'string' : true);
  const common = (a, b) => { a = a.toLowerCase(); b = b.toLowerCase(); let i = 0; while (i < a.length && a[i] === b[i]) i++; return i; };
  for (const k of extra) {
    const cand = left.filter(m => fits(v[k], s.properties[m]));
    if (!cand.length) continue;
    const best = cand.reduce((b, m) => (common(k, m) > common(k, b) ? m : b));
    left = left.filter(m => m !== best);
    out[best] = fixArgs(v[k], s.properties[best]);
  }
  return out;
};

